import assert from "node:assert/strict";

function stableSettings(settings) {
  const snapshot = structuredClone(settings);
  // The retired NPU status is generated by getStatus() on every read.
  // Keep all status/configuration fields exact except its observation timestamp.
  if (snapshot.npu?.status?.updatedAt !== undefined) {
    assert.ok(Number.isFinite(Date.parse(snapshot.npu.status.updatedAt)));
    delete snapshot.npu.status.updatedAt;
  }
  return snapshot;
}

function assertAuthPlanIntent(plan, before, request) {
  assert.equal(plan.origin.surface, "settings");
  assert.equal(plan.origin.workspaceId, "default");
  assert.equal(plan.origin.sessionId, undefined);
  assert.equal(plan.origin.turnId, undefined);
  assert.equal(plan.scope, "runtime");
  assert.equal(plan.kind, "runtime_configuration");
  assert.deepEqual(plan.adapter, { adapterId: "runtime-configuration", version: 2 });
  assert.deepEqual(plan.target, {
    ownerId: "runtime_settings",
    resourceId: "gateway_auth_configuration",
    expectedRevision: before.revision,
  });
  assert.deepEqual(plan.request, {
    kind: "runtime_configuration",
    change: {
      operation: "gateway_auth_configuration",
      mode: "token",
      allowLoopbackBypass: request.allowLoopbackBypass,
    },
  });
}

export function assertFirstRunAuthFixture({ before, request, receipt, authReceipt, after, plan }) {
  assert.equal(before.auth.mode, "token");
  assert.equal(before.auth.tokenConfigured, true);
  assert.ok(Number.isSafeInteger(before.revision) && before.revision > 0);
  assert.deepEqual(Object.keys(request).sort(), ["allowLoopbackBypass", "expectedRevision"]);
  assert.equal(request.expectedRevision, before.revision);
  assert.equal(typeof request.allowLoopbackBypass, "boolean");
  assert.notEqual(request.allowLoopbackBypass, before.auth.allowLoopbackBypass);
  assert.deepEqual(
    stableSettings(after),
    stableSettings({
      ...before,
      revision: before.revision + 1,
      auth: { ...before.auth, allowLoopbackBypass: request.allowLoopbackBypass },
    }),
  );
  const { changePlanReceipt, ...initialAuthReceipt } = receipt;
  assert.deepEqual(authReceipt, { revision: after.revision, ...after.auth });
  if (before.features?.evolutionControlPlaneV1Enabled) assert.ok(changePlanReceipt, "Governed auth receipt missing.");
  if (!changePlanReceipt) {
    assert.deepEqual(initialAuthReceipt, authReceipt);
    assert.equal(plan, undefined);
    return;
  }
  assert.ok(changePlanReceipt.planId && Number.isSafeInteger(changePlanReceipt.revision));
  assert.equal(plan.planId, changePlanReceipt.planId);
  assert.ok(plan.revision >= changePlanReceipt.revision);
  assert.equal(plan.status, "completed");
  assert.equal(plan.requiredAction, undefined);
  if (changePlanReceipt.status === "awaiting_approval") {
    assert.deepEqual(initialAuthReceipt, { revision: before.revision, ...before.auth });
    assert.equal(changePlanReceipt.requiredAction.kind, "approval");
    assert.ok(plan.approvalRefs.includes(changePlanReceipt.requiredAction.approvalId));
    assert.ok(plan.revision > changePlanReceipt.revision);
  } else {
    assert.equal(changePlanReceipt.status, plan.status);
    assert.equal(plan.revision, changePlanReceipt.revision);
    assert.equal(changePlanReceipt.requiredAction, undefined);
    assert.deepEqual(initialAuthReceipt, authReceipt);
  }
  assertAuthPlanIntent(plan, before, request);
  assert.equal(plan.result.appliedRevision, after.revision);
  assert.ok(Number.isFinite(Date.parse(plan.appliedAt)));
}

/** Fixture-only actual owner calls. Never sends or replaces a credential. */
export async function setFirstRunFixtureAuthBypass(api, allowLoopbackBypass) {
  const before = await api("/api/v1/settings");
  assert.equal(before.auth.mode, "token");
  assert.equal(before.auth.tokenConfigured, true);
  if (before.auth.allowLoopbackBypass === allowLoopbackBypass) return { before, after: before };
  const onboardingBefore = await api("/api/v1/onboarding/state");
  assert.equal(onboardingBefore.settings.revision, before.revision);
  const request = { expectedRevision: before.revision, allowLoopbackBypass };
  const receipt = await api("/api/v1/auth/settings", { method: "PATCH", body: request });
  const readPlan = () =>
    api(`/api/v1/change-plans/${encodeURIComponent(receipt.changePlanReceipt.planId)}?workspaceId=default`);
  let plan = receipt.changePlanReceipt ? await readPlan() : undefined;
  if (plan?.status === "awaiting_approval") {
    assertAuthPlanIntent(plan, before, request);
    assert.equal(plan.planId, receipt.changePlanReceipt.planId);
    assert.equal(plan.revision, receipt.changePlanReceipt.revision);
    assert.deepEqual(plan.requiredAction, receipt.changePlanReceipt.requiredAction);
    assert.equal(plan.requiredAction.kind, "approval");
    const approvalId = plan.requiredAction.approvalId;
    assert.ok(approvalId && plan.approvalRefs.includes(approvalId));
    const replay = await api(`/api/v1/approvals/${encodeURIComponent(approvalId)}/replay`);
    const approval = replay.approval;
    assert.equal(approval.approvalId, approvalId);
    assert.equal(approval.kind, "change_plan_effect");
    assert.equal(approval.status, "pending");
    assert.equal(approval.linkage.workspaceId, "default");
    for (const [key, value] of Object.entries({
      planId: plan.planId,
      kind: plan.kind,
      scope: plan.scope,
      intentHash: plan.intentHash,
      targetOwnerId: plan.target.ownerId,
      targetResourceId: plan.target.resourceId,
      targetRevision: plan.target.expectedRevision,
      targetHash: plan.target.expectedHash,
      adapterId: plan.adapter.adapterId,
      adapterVersion: plan.adapter.version,
    }))
      assert.deepEqual(approval.payload[key], value);
    assert.deepEqual(
      stableSettings(await api("/api/v1/settings")),
      stableSettings(before),
      "Pending auth plan applied early.",
    );
    const decision = await api(`/api/v1/approvals/${encodeURIComponent(approvalId)}/resolve`, {
      method: "POST",
      body: {
        decision: "approve",
        resolutionNote:
          "Approve only this isolated verification runtime's token-auth loopback posture; keep its existing synthetic token.",
      },
    });
    assert.equal(decision.approval.approvalId, approvalId);
    assert.equal(decision.approval.status, "approved");
    const approvedPlan = await readPlan();
    assertAuthPlanIntent(approvedPlan, before, request);
    assert.equal(approvedPlan.planId, plan.planId);
    assert.equal(approvedPlan.status, "awaiting_approval");
    assert.equal(approvedPlan.requiredAction.kind, "approval");
    assert.equal(approvedPlan.requiredAction.approvalId, approvalId);
    assert.deepEqual(
      stableSettings(await api("/api/v1/settings")),
      stableSettings(before),
      "Approval alone applied the auth change.",
    );
    const continued = await api(`/api/v1/change-plans/${encodeURIComponent(plan.planId)}/responses`, {
      method: "POST",
      body: {
        workspaceId: "default",
        expectedRevision: approvedPlan.revision,
        actionId: approvedPlan.requiredAction.actionId,
        actionNonce: approvedPlan.requiredAction.actionNonce,
        values: {},
      },
    });
    plan = await readPlan();
    assert.deepEqual(continued, plan, "Auth continuation receipt differs from its canonical plan.");
  }
  const after = await api("/api/v1/settings");
  const authReceipt = await api("/api/v1/auth/settings");
  assertFirstRunAuthFixture({ before, request, receipt, authReceipt, after, plan });
  const onboardingAfter = await api("/api/v1/onboarding/state");
  assert.equal(onboardingAfter.settings.revision, after.revision);
  for (const key of ["completed", "completedAt", "completedBy"])
    assert.deepEqual(onboardingAfter[key], onboardingBefore[key], `Auth fixture changed onboarding ${key}.`);
  const firstTaskEvidence = (task) => {
    if (!task) return task;
    const { checkedAt, ...evidence } = task;
    if (checkedAt !== undefined) assert.ok(Number.isFinite(Date.parse(checkedAt)));
    return evidence;
  };
  assert.deepEqual(
    firstTaskEvidence(onboardingAfter.firstTask),
    firstTaskEvidence(onboardingBefore.firstTask),
    "Auth fixture changed canonical first-task evidence.",
  );
  return { before, receipt, authReceipt, after, plan };
}
